<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Database;use App\Services\McpOAuthService;header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');if(($_SERVER['REQUEST_METHOD']??'')!=='POST'){http_response_code(405);echo json_encode(['error'=>'invalid_request']);exit;}$raw=(string)file_get_contents('php://input');$input=json_decode($raw,true);try{$client=McpOAuthService::registerClient(Database::connection(),is_array($input)?$input:[]);http_response_code(201);echo json_encode($client,JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(400);echo json_encode(['error'=>'invalid_client_metadata','error_description'=>$e->getMessage()]);}
